# thread.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$defs": {
    "message_ref": {
      "additionalProperties": false,
      "properties": {
        "from": {
          "minLength": 1,
          "type": "string"
        },
        "kind": {
          "enum": [
            "msg",
            "question",
            "status",
            "directive",
            "task",
            "report",
            "incident"
          ]
        },
        "reply_to": {
          "minimum": 1,
          "type": [
            "integer",
            "null"
          ]
        },
        "seq": {
          "minimum": 1,
          "type": "integer"
        },
        "ts": {
          "format": "date-time",
          "type": "string"
        }
      },
      "required": [
        "seq",
        "kind",
        "reply_to",
        "from",
        "ts"
      ],
      "type": "object"
    }
  },
  "$id": "https://coding-hermes.local/chd32/schemas/thread.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "description": "A reply tree rooted at one room sequence. The tree is the durable work log; it is not a reconstructed Hermes transcript.",
  "properties": {
    "assignment_seq": {
      "minimum": 1,
      "type": [
        "integer",
        "null"
      ]
    },
    "child_thread_ids": {
      "items": {
        "pattern": "^th-[a-z0-9][a-z0-9-]*$",
        "type": "string"
      },
      "type": "array",
      "uniqueItems": true
    },
    "generation": {
      "minimum": 1,
      "type": "integer"
    },
    "messages": {
      "items": {
        "$ref": "#/$defs/message_ref"
      },
      "type": "array"
    },
    "owner_agent": {
      "minLength": 1,
      "type": "string"
    },
    "parent_seq": {
      "minimum": 1,
      "type": [
        "integer",
        "null"
      ]
    },
    "parent_thread_id": {
      "type": [
        "string",
        "null"
      ]
    },
    "retired_generation": {
      "default": false,
      "type": "boolean"
    },
    "room_id": {
      "pattern": "^(obj|task|space)-[a-z0-9][a-z0-9-]*$",
      "type": "string"
    },
    "root_seq": {
      "minimum": 1,
      "type": "integer"
    },
    "schema_version": {
      "const": 1
    },
    "state": {
      "enum": [
        "open",
        "waiting",
        "reported",
        "closed"
      ]
    },
    "thread_id": {
      "pattern": "^th-[a-z0-9][a-z0-9-]*$",
      "type": "string"
    },
    "work_uid": {
      "minLength": 1,
      "type": "string"
    }
  },
  "required": [
    "schema_version",
    "thread_id",
    "room_id",
    "root_seq",
    "parent_thread_id",
    "parent_seq",
    "owner_agent",
    "work_uid",
    "assignment_seq",
    "state",
    "generation",
    "messages"
  ],
  "title": "CHD Thread",
  "type": "object"
}
```
